const localTime=(value,zone,seconds=false)=>formatTime(value,zone,seconds,locale());
const $=s=>document.querySelector(s), app=$('#app'),modal=$('#modal');
const store=new Store();let formSave=Promise.resolve(),updateReady=false,editVersion=0,formDirty=false,pendingExports=[],exportSnapshot=null;let snapshot,state,local,view='field',selected=null,urls=new Map(),pendingImport=null,sample=null,saving=0,search='',toastTimer;
let availableUpdate=null,cleanupPlan=null;const selectedAssets=new Set();
let lightCapability={available:false,mode:'checking',title:tr('Checking built-in light meter…'),detail:''};
const androidDownload='https://github.com/Devilzhu1985/hk-scout/releases/download/v2.1.4-preview.1/scout-2.1.4-preview.1-debug.apk';
const weatherPending=new Set(),weatherErrors=new Map();
function weatherHTML(s,compact=false){
 const w=s.weather;
 if(w){const values=[tr(weatherLabel(w.code)),w.temperatureC===null?null:fmt(w.temperatureC)+' °C',w.cloudCover===null?null:tr('Cloud')+' '+fmt(w.cloudCover)+'%',w.windKmh===null?null:tr('Wind')+' '+fmt(w.windKmh)+' km/h',w.precipitationMm===null?null:tr('Precipitation')+' '+fmt(w.precipitationMm)+' mm / '+Math.round(w.intervalSeconds/60)+' min'].filter(Boolean).join(' · ');
 return html`<div class="weather-snapshot"><b>Weather · online estimate</b><div>${e(values)}</div><small><a href="${WEATHER_SOURCE_URL}" target="_blank" rel="noopener">Open-Meteo</a> · ${e(localTime(w.validAt,w.timezone))} · ${e(w.timezone)}</small>${compact?'':html('<small>Saved near capture time. Nearby model conditions may differ from this street or indoor scene. Add observed differences in notes.</small>')}</div>`;}
 const message=weatherPending.has(s.id)?tr('Getting weather for this location…'):local.onlineWeather===false?tr('Automatic weather is off.'):weatherErrors.get(s.id)||tr('Weather waits for a fresh GPS fix and internet.');
 return html`<div class="weather-snapshot"><b>Weather · online estimate</b><small>${e(message)}</small>${!compact&&!s.endedAt&&local.onlineWeather!==false?button(tr('Retry GPS & weather'),'gps',s.id,'quiet'):''}</div>`;
}
async function autoWeather(id,fix){
 const current=get(state,id);if(weatherPending.has(id)||local.onlineWeather===false||!current||current.weather||current.endedAt||Math.abs(Date.now()-Date.parse(current.startedAt))>3600000)return;
 if(!navigator.onLine){weatherErrors.set(id,tr('Weather unavailable offline. Keep shooting.'));render();return;}
 weatherPending.add(id);weatherErrors.delete(id);render();
 try{const weather=await lookupWeather(fix);if(!weather)throw Error('unavailable');await change(s=>{if(local.onlineWeather===false)return;const current=get(s,id),updates=automaticWeatherChanges(current,fix,weather);if(Object.keys(updates).length)put(s,revise(current,updates,local.device.id));});}
 catch{weatherErrors.set(id,tr('Weather unavailable. Keep shooting or retry GPS & weather.'));}
 finally{weatherPending.delete(id);render();}
}

const gpsPending=new Set(),gpsErrors=new Map(),dirtyFields=new Set(),savedVersions=new Map();
const roles=['unclassified','identification','environment','material','lighting','gray reference','bracket','panorama','detail','signage'];
const fmt=n=>Number.isFinite(n)?Number(n.toFixed(2)).toLocaleString(locale()):'—';
const button=(label,action,id='',cls='')=>html`<button class="${cls}" data-action="${action}" data-id="${e(id)}">${tr(label)}</button>`;
const trip=()=>{const r=get(state,local.activeTrip);return r&&!r.deleted?r:null;};
const sets=()=>active(state,'set').filter(s=>s.tripId===local.activeTrip);
const fieldsets=()=>sets().sort((a,b)=>b.startedAt.localeCompare(a.startedAt));
const fieldAssets=()=>active(state,'asset').filter(a=>a.tripId===local.activeTrip);
const notice=(text,error=false)=>{clearTimeout(toastTimer);$('#notice').textContent=tr(text);$('#notice').className='show'+(error?' error':'');toastTimer=setTimeout(()=>$('#notice').className='',error?10000:4500);};
function labelFields(root){for(const label of root.querySelectorAll('label:not([for])')){const input=label.nextElementSibling;if(input?.matches('input,select,textarea')){input.id ||= 'field-'+uid();label.htmlFor=input.id;}}}
function show(html){stopSlateTimer();modal.innerHTML=html;labelFields(modal);modal.showModal();modal.scrollTop=0;}
function close(){modal.close();stopMeter();}
async function refresh(){snapshot=await store.read();state=snapshot.state;local=snapshot.local;setLanguage(local.language||(/^zh/i.test(navigator.language)?'zh':'en'));const previews=new Set(state.records.filter(r=>r.kind==='asset'&&!r.deleted).map(r=>r.blobId));const present=new Set(snapshot.blobs.map(b=>b.id));for(const [id,url]of urls)if(!previews.has(id)||!present.has(id)){URL.revokeObjectURL(url);urls.delete(id);}for(const id of selectedAssets)if(!fieldAssets().some(a=>a.id===id))selectedAssets.delete(id);for(const b of snapshot.blobs)if(previews.has(b.id)&&!urls.has(b.id))urls.set(b.id,URL.createObjectURL(b.blob));}
function savedLabel(){const el=$('#saved');if(el)el.textContent=saving?tr('Saving…'):formDirty?tr('Unsaved edit · leave field to save'):tr('Saved on this device');}
async function change(fn,redraw=true){saving++;savedLabel();try{await store.change(fn);await refresh();if(redraw)render();}catch(err){notice(tr('Not saved: ')+tr(err.message),true);throw err;}finally{saving--;savedLabel();}}
function patch(id,changes){return change(s=>{const r=get(s,id);if(!r||r.purgedAt)throw Error(tr('Record no longer exists'));put(s,revise(r,changes,local.device.id));});}
const dateKey=(value,tz)=>new Intl.DateTimeFormat('en-CA',{timeZone:tz,year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(value));
const mapLink=s=>s.location?`https://www.google.com/maps/search/?api=1&query=${s.location.lat},${s.location.lng}`:`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent([s.name,s.city].filter(Boolean).join(', '))}`;
function gpsText(s){return s.location?`${s.location.lat.toFixed(5)}, ${s.location.lng.toFixed(5)}${s.location.accuracy!=null?' · ±'+Math.round(s.location.accuracy)+' m':''}${s.location.capturedAt?' · '+tr('fix')+' '+localTime(s.location.capturedAt,s.timezone):''}`:tr('Location not recorded');}

function connection(){ $('#connection').textContent=(navigator.onLine?tr('On device'):tr('Offline'))+' · '+(native?tr('Scout for Android'):tr('Scout in browser')); }
function render(){
  document.documentElement.lang=getLanguage()==='zh'?'zh-CN':'en';$('#language').value=getLanguage();$('#update-label').textContent=tr('Update Scout');$('#update button').textContent=tr('Update app · saves first, then reloads');$('.brand span').textContent=tr('FIELD NOTES');$('#nav').setAttribute('aria-label',tr('Main navigation')); document.title=tr('Scout · Field reference notebook');
  const oldForm=$('#set-form'),focused=document.activeElement;
  const expanded=oldForm?.dataset.set===selected?[...app.querySelectorAll('details[id][open]')].map(el=>el.id):[];
  const draft=formDirty&&view==='field'&&oldForm?.dataset.set===selected?{values:[...new FormData(oldForm)],focus:focused?.name,start:focused?.selectionStart,end:focused?.selectionEnd}:null;
  const links=[['field','⌖',tr('Field')],['library','▦',tr('Library')],['transfer','⇄',tr('Transfer')],['settings','⚙',tr('Trips & kit')]];
  $('#nav').innerHTML=links.map(([v,icon,title])=>html`<button data-action="nav" data-id="${v}" class="${view===v?'on':''}"><span>${icon}</span>${tr(title)}</button>`).join('');
  connection();
  if(!trip()&&view!=='settings'&&view!=='transfer'){app.innerHTML=welcome();return;}
  if(view==='field')app.innerHTML=selected&&get(state,selected)&&!get(state,selected).deleted?editor(get(state,selected)):field();
  if(view==='library')app.innerHTML=library();
  if(view==='transfer')app.innerHTML=transfer();
  if(view==='settings')app.innerHTML=settings();
  formDirty=!!draft;labelFields(app);for(const id of expanded){const el=document.getElementById(id);if(el)el.open=true;}
  if(draft&&$('#set-form')){const form=$('#set-form');for(const [name,value]of draft.values)if(form.elements[name])form.elements[name].value=value;const input=form.elements[draft.focus];if(input){input.focus({preventScroll:true});if(draft.start!=null&&input.setSelectionRange)input.setSelectionRange(draft.start,draft.end);}}
  savedLabel();
  $('#update').hidden=!updateReady;
}
function welcome(){return html`<div class="split"><section class="card hero"><div class="eyebrow" style="color:#d8e891">A field notebook for the way you see</div><h1>Bring the place<br>back with you.</h1><p class="muted">Sony originals. Phone observations. One connected reference library.</p>${button(tr('Capture here now'),'quick-start','','primary')} ${button(tr('Plan a trip'),'new-trip')}</section><section class="card"><h2>From street to studio</h2><p>01 &nbsp; Capture a place and photograph its code.</p><p>02 &nbsp; Save light readings, reference photos and observations.</p><p>03 &nbsp; Match camera originals on your computer and prepare a review package.</p><small>Works offline after the first load. Hong Kong is an optional starting itinerary.</small></section></div>`;}
function field(){const t=trip(),all=fieldsets(),open=all.filter(s=>!s.endedAt),readings=active(state,'reading').filter(r=>r.tripId===t.id);const last=all.find(s=>s.location);const light=last?daylight(dateKey(now(),last.timezone),last.location.lat,last.location.lng,last.timezone):null;
return html`<div class="heading row between"><div><div class="eyebrow">${e(t.city||tr('Anywhere'))} · ${e(t.timezone)}</div><h1>${e(t.name)}</h1></div>${button(tr('Switch trip'),'nav','settings')}</div>
${captureElsewhere()}${nextDestinationCard()}<div class="split"><section class="card hero"><span class="tag live">FIELD CAPTURE</span><h2 style="font-size:29px;margin-top:18px">Found something worth keeping?</h2><p class="muted">Start a photo set anywhere. Photograph its code with your Sony, then get back to the scene.</p>${button(tr('+ Capture here'),'capture','','primary')} ${button(tr('Choose next stop'),'choose-next')}${open.length?html`<p>${open.length} open set${getLanguage()==='en'&&open.length>1?'s':''} · ${button(tr('Continue ')+e(open[0].code),'open',open[0].id)}</p>`:''}</section><section class="card"><div class="grid three"><div><div class="stat">${all.length}</div><small>Photo sets</small></div><div><div class="stat">${readings.length}</div><small>Light readings</small></div><div><div class="stat">${fieldAssets().length}</div><small>Images linked or waiting</small></div></div><hr class="divider">${light?html`<small>Solar estimate at your last recorded position</small><p>${tr(light.polar)||html`Sunrise ${localTime(light.rise,last.timezone)}<br>Sunset ${localTime(light.set,last.timezone)}`}</p><small>Buildings, hills and weather change the light on the street.</small>`:html('<p class="muted">A GPS fix or manual coordinates unlock local sunrise and sunset estimates.</p>')}</section></div>
<div class="row between"><h2>Your stops</h2><small>Each return visit is a new photo set</small></div>${all.length?all.map(s=>html`<section class="card"><div class="row between"><div><span class="tag ${s.endedAt?'':'live'}">${e(s.code)} · ${s.endedAt?tr('FINISHED'):tr('OPEN')}</span><h2 style="margin-top:12px">${e(s.name||tr('Untitled stop'))}</h2><small>${e(localTime(s.startedAt,s.timezone))} · ${e(s.city)}</small></div><div class="row">${button(tr('Open'),'open',s.id,'primary')}${button(tr('Revisit'),'revisit',s.id)}${button(tr('Delete stop'),'purge',s.id,'quiet danger')}</div></div><p class="muted">${e(s.notes.slice(0,180)||tr('Add observations when you have a moment.'))}</p></section>`).join(''):html('<div class="empty">Your first capture starts here. No itinerary required.</div>')}
${t.template==='hongkong'?html`<details class="card"><summary>Hong Kong itinerary · optional suggestions</summary>${days.map((d,dayIndex)=>html`<details><summary>${e(getLanguage()==='zh'?d.t:d.en)}</summary>${d.slots.map(([label,ids],slotIndex)=>html`<small>${e(getLanguage()==='zh'?label:({'白天':'Daytime','傍晚':'Dusk','夜晚':'Night','有空就补':'Flexible additions'}[label]||label))}</small>${ids.map(id=>{const p=places.find(p=>p.id===id);return html`<div class="list-item row between"><div><b>${e(getLanguage()==='zh'?p.n:p.en)}</b><p class="muted">${e(getLanguage()==='zh'?p.d:p.descriptionEn)}</p></div><div>${button(tr('Capture here'),'place',itineraryKey(dayIndex,slotIndex,id))} ${button(tr('Directions'),'plan-route',itineraryKey(dayIndex,slotIndex,id))}<small>${tr('Finished captures')}: ${all.filter(s=>s.plannedStopKey===itineraryKey(dayIndex,slotIndex,id)&&s.endedAt).length}</small></div></div>`;}).join('')}`).join('')}</details>`).join('')}<small>Suggestions are inherited from the original itinerary. Check current access and opening times yourself.</small></details>`:''}`;}

function editor(s){const readings=active(state,'reading').filter(r=>r.setId===s.id),assets=active(state,'asset').filter(a=>a.setId===s.id);const exposure=ev100(Number(s.camera.aperture),shutterSeconds(s.camera.shutter),Number(s.camera.iso));
return html`<div class="heading"><div class="row between">${button(tr('‹ All stops'),'back')}<span id="saved" class="status"></span></div><div class="row between"><div><div class="eyebrow">${e(s.code)} · ${s.endedAt?tr('Finished'):tr('Open photo set')}</div><h1>${e(s.name||tr('Untitled stop'))}</h1></div>${button(tr('Show camera slate'),'slate',s.id)}</div><small>${e(localTime(s.startedAt,s.timezone))}${s.endedAt?' → '+e(localTime(s.endedAt,s.timezone)):''} · ${e(s.timezone)}</small></div>
${nextStep(s,assets,readings)}<div class="split"><div><section class="card"><h2>The place</h2><p>${gpsPending.has(s.id)?tr('Finding your location…'):gpsErrors.get(s.id)?e(gpsErrors.get(s.id)):tr(s.location?'Location saved automatically; edit the name only if useful.':'You can keep shooting without a location.')}</p>${s.placeLookup?'<small>'+tr('Nearby area / street estimate; verify the exact subject.')+' · '+e(s.placeLookup.source)+'</small>':''}<form id="set-form" data-set="${e(s.id)}"><div class="form-grid"><div class="wide"><label for="set-name">Place name (optional)</label><input id="set-name" name="name" maxlength="300" value="${e(s.name)}"></div><details class="wide"><summary>Place details & capture options</summary><div class="form-grid"><div><label>City / destination</label><input name="city" value="${e(s.city)}" maxlength="200"></div><div><label>Capture mode</label><select name="mode"><option value="quick" ${s.mode==='quick'?'selected':''}>Quick reference</option><option value="survey" ${s.mode==='survey'?'selected':''}>Lighting survey</option></select></div></div></details><div class="wide"><label>Observations</label><textarea name="notes" maxlength="4000" placeholder="Light sources, weather, materials, useful angles…">${e(s.notes)}</textarea></div></div><div class="row">${button(tr('Get fresh GPS'),'gps',s.id)}${button(tr('Enter coordinates'),'coords',s.id)}<a class="button quiet" href="${e(mapLink(s))}" target="_blank" rel="noopener">Open map ↗</a></div><p class="muted" style="font-size:12px">${e(gpsText(s))}</p><div id="capture-weather">${weatherHTML(s)}</div><small>Capture time is saved automatically from this device. Keep automatic date and time enabled on your phone.</small><details><summary>Camera snapshot and file boundaries</summary><div class="form-grid"><div><label>Camera (EXIF model name)</label><input name="cameraName" value="${e(s.camera.name)}" maxlength="200"></div><div><label>Fixed white balance, K</label><input name="wb" type="number" min="1000" max="50000" value="${e(s.camera.wb??'')}"></div><div><label>Aperture</label><input name="aperture" type="number" min="0.5" max="128" step="0.1" value="${e(s.camera.aperture??'')}"></div><div><label>ISO</label><input name="iso" type="number" min="1" value="${e(s.camera.iso||'')}"></div><div><label>Shutter, seconds or fraction</label><input name="shutter" value="${e(s.camera.shutter||'')}" placeholder="1/125"></div><div><label>First / last Sony filenames (optional)</label><input name="files" value="${e(s.files||'')}" placeholder="DSC01234 → DSC01258" maxlength="500"></div></div><small>Settings are saved with this set. Original EXIF remains authoritative for individual images. ${exposure!==null?tr('Exposure setting EV100: ')+fmt(exposure)+tr('. This is not measured scene lux.'):''}</small></details><p><button type="submit" class="primary">Save record</button></p><small>Edits save when you leave a field; wait for “Saved” before closing.</small></form></section>
<section class="card"><div class="row between"><h2>Reference images</h2><div class="row">${button(tr('Take photo'),'camera',s.id,'primary')}${button(tr('+ Add images'),'photo',s.id)}</div></div><p class="muted">Phone originals are kept unchanged alongside small previews. Sony originals stay on your computer.</p><div class="thumbs">${assets.map(a=>html`<figure>${a.blobId&&urls.get(a.blobId)?html`<img src="${urls.get(a.blobId)}" alt="${e(a.fileName)}">`:html('<div class="empty">No preview</div>')}<figcaption>${e(a.fileName)} · ${e(tr(a.role||'unclassified'))}</figcaption><div class="row">${button(tr('Color sample'),'color',a.id,'quiet')}${button(tr('Edit'),'asset',a.id,'quiet')}${button(tr('Delete image'),'purge',a.id,'quiet danger')}</div></figure>`).join('')}</div></section>
</div><div><details class="card" id="lighting-details" ${readings.length||s.mode==='survey'?'open':''}><summary>Lighting details & readings</summary><div class="row between"><h2>Lighting</h2><span class="tag">WITH PROVENANCE</span></div><p class="muted">Save readings at a named position. Keep the phone orientation consistent when comparing light.</p>${lightingActions(s.id)}${readings.length?readings.map(r=>html`<div class="list-item"><div class="row between"><b>${e(r.label||tr('Reading'))}</b><span>${fmt(r.value)} ${r.method.endsWith('lux')?'lux':'EV100'}</span></div><p>${e(r.instrument)} · ${e(tr(r.method))}</p><small>${e(r.protocol)} · ${e(tr(r.calibration))}</small>${r.samples?html`<p class="muted">Range ${fmt(r.samples.min)}–${fmt(r.samples.max)} · ${r.samples.count} samples</p>`:''}<div>${button(tr('Remove'),'delete',r.id,'quiet danger')}</div></div>`).join(''):html('<p class="muted">No measurements yet. Missing readings stay empty.</p>')}${comparison(readings)}</details>
<details class="card"><summary>Checklist & archive</summary><h2>Before you leave</h2><p>□ Code photographed on the Sony<br>□ Establishing view and useful details<br>□ ${s.mode==='survey'?html('Reference target and light readings<br>□ Brackets / lighting zones checked'):tr('One representative reference frame')}</p><div class="alert">Sony lens cover: uncalibrated target. Image samples describe rendered color, not measured Kelvin or physical albedo.</div>${s.endedAt?button(tr('Reopen this set'),'reopen',s.id):button(tr('Finish without more steps'),'finish',s.id)} ${button(tr('Archive set'),'delete',s.id,'quiet')} ${button(tr('Delete stop'),'purge',s.id,'danger')}</details></div></div>`;}
function comparison(rs){const a=rs.at(-2),b=rs.at(-1);return a&&b&&comparable(a,b)?html`<div class="alert success">Last two comparable readings: ${fmt(b.value/a.value)}× · ${fmt(Math.log2(b.value/a.value))} stops (${e(b.label)} relative to ${e(a.label)}). Relative, uncalibrated comparison.</div>`:rs.length>1?html('<small>Ratios are shown only for positive readings from the same instrument, method, orientation protocol and calibration status.</small>'):'';}

const visibleAssets=()=>fieldAssets().filter(a=>[a.fileName,a.role,tr(a.role),a.notes,...(a.tags||[])].join(' ').toLowerCase().includes(search.toLowerCase()));
function library(){const t=trip(),assets=visibleAssets(),clocks=active(state,'clock').filter(c=>c.tripId===t.id);return html`<div class="heading"><div class="eyebrow">STUDIO REVIEW</div><h1>The reference library</h1><p class="muted">${e(t.name)} · ${tr('Sony files stay external. Scout copies can be deleted below.')}</p><div class="row">${button(tr('Import camera catalogue'),'import','','primary')}${button(tr('Camera clock segments'),'clocks')}${button(tr('Confirm unique suggestions'),'confirm-suggestions')}</div></div><label for="search">Search filenames, roles and notes</label><input id="search" value="${e(search)}" placeholder="Concrete, neon, DSC01234…"><p><small>Run the desktop importer to prepare camera metadata and previews. Imports never assign a photo set without your confirmation.</small></p><div class="selection-bar"><b>${tr('Selected images')}: ${selectedAssets.size}</b><div class="row">${button(tr('Select shown'),'select-images')}${selectedAssets.size?button(tr('Clear selection'),'clear-images')+button(tr('Delete selected'),'purge-images','','danger'):''}</div></div><div class="grid three">${assets.map(a=>{const hint=!a.setId&&a.source==='camera'?suggest(a,sets(),clocks):null;const set=get(state,a.setId);return html`<section class="card asset"><label class="image-select"><input type="checkbox" data-select-image="${e(a.id)}" ${selectedAssets.has(a.id)?'checked':''}><span>${tr('Select image')} · ${e(a.fileName)}</span></label>${a.blobId&&urls.has(a.blobId)?html`<img loading="lazy" src="${urls.get(a.blobId)}" alt="${e(a.fileName)}">`:html('<div class="empty">Preview unavailable</div>')}<h3 style="margin-top:12px">${e(a.fileName)}</h3><span class="tag ${set?'':'warn'}">${set?e(set.code):tr('UNRESOLVED')}</span> <span class="tag">${e(a.role||'unclassified')}</span><p class="muted">${e(a.notes||'')}</p><small>${e(a.originalRelativePath||tr('Phone reference'))}${a.captureWall?html('<br>Camera clock: ')+e(a.captureWall):''}</small>${hint?html`<p class="muted">${hint.sets.length===1?tr('Suggested: ')+e(hint.sets[0].code):hint.sets.length>1?tr('Ambiguous: overlapping sets'):e(hint.reason)+(hint.time?' · no closed set contains this time':'')}</p>`:''}<div class="row">${button(tr('Assign / describe'),'asset',a.id)}${a.blobId?button(tr('Color'),'color',a.id,'quiet'):''}${button(tr('Delete image'),'purge',a.id,'quiet danger')}</div></section>`;}).join('')}</div>${assets.length?'':html('<div class="empty">Import camera previews, or add reference images while capturing a set.</div>')}`;}
function transfer(){const t=trip(),conflicts=state.conflicts,deleted=state.records.filter(r=>r.deleted&&!r.purgedAt);return html`<div class="heading"><div class="eyebrow">DEVICE → STUDIO → DEVICE</div><h1>Bring everything together.</h1><p class="muted">Portable ZIP packages include records, previews and checksums. Imports merge changes.</p></div><div class="grid"><section class="card"><h2>Export ${e(t?.name||'a trip')}</h2><p>Keep an independent copy before clearing cards or browser data.</p><div class="row">${button(tr('Field backup'),'export','backup','primary')}${button(tr('Prepare AI handoff'),'export','handoff')}</div><p><small>${local.lastExport?tr('Last export handed to your device: ')+e(localTime(local.lastExport,'UTC'))+tr(' UTC. Destination and second-copy verification are still your responsibility.'):tr('No export recorded on this device.')}</small></p><p><small>Active trip only · Large trips split into parts · phone originals included; Sony originals external</small></p></section><section class="card"><h2>Import / verify a package</h2><p>Review additions and conflicts before applying. Reading a package also verifies its preview checksums.</p>${button(tr('Choose package'),'import','','primary')}<p><small>Scout ZIP, desktop catalogue ZIP, or original v1 JSON backup.</small></p></section></div><section class="card"><h2>Desktop RAW importer</h2><p>After copying the Sony card, run this from the repository on your computer:</p><pre>npm run catalogue -- --input "D:/Photos/Trip/Originals" --output "D:/Photos/Trip/Review"</pre><p class="muted">Creates resumable metadata, previews and import batches. Choose each catalogue ZIP above, add a clock segment, and review suggested matches.</p><small>The importer reads originals. It never renames, moves, deletes or writes metadata into them.</small></section>
<section class="card"><h2>Conflicts · ${conflicts.length}</h2>${conflicts.map(c=>{const current=get(state,c.incoming.id);return html`<div class="list-item"><b>${e(current.name||current.fileName||current.label||current.code||current.id)}</b><div class="grid"><div><p>This device ${current.deleted?'(deleted)':''}</p><pre>${e(JSON.stringify(current,null,2))}</pre>${button(tr('Keep this version'),'resolve-local',c.id)}</div><div><p>Incoming ${c.incoming.deleted?'(deleted)':''}</p><pre>${e(JSON.stringify(c.incoming,null,2))}</pre>${button(tr('Use incoming version'),'resolve-incoming',c.id)}</div></div></div>`;}).join('')||html('<p class="muted">No conflicting edits.</p>')}</section><details class="card"><summary>Recover archived records · ${deleted.length}</summary>${deleted.map(r=>html`<div class="list-item row between"><span>${e(r.kind)} · ${e(r.name||r.fileName||r.label||r.id)}</span><div class="row">${button(tr('Restore'),'restore',r.id)}${button(tr('Delete permanently'),'purge',r.id,'quiet danger')}</div></div>`).join('')}</details>${deletionHistory()}${state.legacy.length?html('<p class="muted">Original v1 metadata is retained in the export archive. Historical global settings are not asserted as capture facts.</p>'):''}`;}
function settings(){const all=active(state,'trip');return html`<div class="heading"><div class="eyebrow">MAKE IT YOUR FIELD NOTEBOOK</div><h1>Trips & equipment</h1></div><div class="grid"><section class="card"><div class="row between"><h2>Your trips</h2>${button(tr('+ New trip'),'new-trip','','primary')}</div>${all.map(t=>html`<div class="list-item row between"><div><b>${e(t.name)}</b><p class="muted">${e(t.city)} · ${e(t.timezone)}</p></div><div class="row">${button(t.id===local.activeTrip?tr('Selected'):tr('Use trip'),'select-trip',t.id,t.id===local.activeTrip?'quiet':'')}${button(tr('Delete trip'),'purge',t.id,'quiet danger')}</div></div>`).join('')||html('<p>No trips yet.</p>')}</section><section class="card"><h2>This device & camera defaults</h2><form id="kit-form"><label>Device label</label><input name="deviceName" value="${e(local.device.name)}" maxlength="160" required><label>Camera model (as shown in EXIF)</label><input name="camera" value="${e(local.camera||'ILCE-7CR')}" maxlength="200" required><div class="form-grid"><div><label>White balance default, K</label><input name="wb" type="number" min="1000" max="50000" value="${e(local.wb||'5500')}"></div><div><label>Aperture default</label><input name="aperture" type="number" min="0.5" max="128" step="0.1" value="${e(local.aperture||'')}"></div></div><p><button type="submit" class="primary">Save defaults</button></p><small>Only new sets use these defaults. Existing capture facts remain unchanged.</small></form></section></div>${storagePanel()}<section class="card"><h2>Location names</h2><label class="inline-check"><input type="checkbox" id="place-names" ${local.onlinePlaceNames===true||local.onlinePlaceNames!==false&&nativePlaceNames?'checked':''}>Look up place names online</label><p>${nativePlaceNames?tr('Uses Android’s address provider for the current GPS fix.'):tr('Optional: sends this device’s current GPS coordinates to BigDataCloud for city / area names. It does not identify exact shops.')}</p><p>GPS coordinates save without an online lookup. You can continue offline or when permission is denied.</p></section><section class="card"><h2>Automatic weather & time</h2><label class="inline-check"><input type="checkbox" id="online-weather" ${local.onlineWeather!==false?'checked':''}>Get weather automatically for new stops</label><p>Sends GPS rounded to two decimals to Open-Meteo. Saves nearby weather estimates with source and time; notes remain your on-site observations.</p><p>Capture time comes from the device clock automatically. New stops use the online location time zone when available, unless you edit it. Weather has its own timestamp; it never resets your phone clock or changes old capture times.</p></section><section class="card"><h2>App updates & camera recovery</h2>${button(tr('Check for updates'),'check-update','','primary')}${nativeCamera?button(tr('Recover camera captures'),'recover-captures'):''}<p>Updates preserve this installation’s records. Keep a field backup and approve the Android installer when prompted.</p></section><section class="card"><h2>Capture readiness</h2><p>□ Sony clock and phone time checked<br>□ Code photograph readable<br>□ RAW storage and battery ready<br>□ App opened once online, then tested offline<br>□ Previous shoot exported and verified</p><div class="alert">Live lux: Android sensor when available. iPhone and desktop browsers support manual readings. Camera EV is a separate estimate. No sensor is considered photographically calibrated.</div><p>Reference target: Sony lens cover (uncalibrated). A known neutral gray card improves exposure and color references.</p><small>Scout 2.1.4 · local files first · no analytics or automatic cloud/AI upload</small></section>`;}

async function newSet(name='',source=null){const t=trip();const time=now();const r=record('set',{tripId:t.id,createdDevice:local.device.id,code:'S-'+uid().replaceAll('-','').slice(0,10).toUpperCase(),name:name||tr('Untitled stop'),autoName:!name,city:source?.city||t.city,timezone:source?.timezone||t.timezone,autoTimezone:true,startedAt:time,endedAt:null,mode:'quick',notes:'',tags:[],files:'',location:null,plannedStopKey:source?.plannedStopKey||null,camera:{name:local.camera||'ILCE-7CR',wb:local.wb?Number(local.wb):5500,aperture:local.aperture?Number(local.aperture):null,iso:'',shutter:''}},local.device.id);await change((s,b,l)=>{for(const old of ownOpenSets(s,l.device.id))put(s,revise(old,{endedAt:time},l.device.id));put(s,r);if(source?.key&&l.nextDestination?.key===source.key&&l.nextDestination.tripId===t.id)delete l.nextDestination;});dirtyFields.clear();formDirty=false;selected=r.id;view='field';render();await slate(r);}
let slateTimer=null;
function stopSlateTimer(){clearInterval(slateTimer);slateTimer=null;}
const slateClock=(value,zone)=>new Intl.DateTimeFormat(locale(),{timeZone:zone,hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}).format(new Date(value));
function slateLightHTML(reading,zone){
 const light=slateLight(reading);if(!light)return html('<div class="slate-light-main"><span>Light reading · optional</span><strong>—</strong></div>');
 const stale=Date.now()-Date.parse(reading.measuredAt)>5*60*1000;
 return html`<div class="slate-light-main"><span>${light.estimated?tr('Estimated EV100 from lux'):tr('Meter EV100 · entered')}</span><strong>${light.ev===null?'—':fmt(light.ev)}</strong></div><small>${light.lux!==null?fmt(light.lux)+' lux · ':''}${e(tr(reading.calibration))} · ${e(slateClock(reading.measuredAt,zone))}</small>${stale?html('<small class="slate-stale">Older reading — remeasure if the light changed.</small>'):''}`;
}
function slateWeatherHTML(s){
 const w=s.weather;if(!w)return weatherHTML(s,true);
 const values=[tr(weatherLabel(w.code)),w.temperatureC===null?null:fmt(w.temperatureC)+' °C',w.cloudCover===null?null:tr('Cloud')+' '+fmt(w.cloudCover)+'%'].filter(Boolean).join(' · ');
 return html`<div class="weather-snapshot"><div>${e(values)}</div><small><a href="${WEATHER_SOURCE_URL}" target="_blank" rel="noopener">Open-Meteo</a> · ${tr('Weather estimate')} · ${e(slateClock(w.validAt,w.timezone))}</small></div>`;
}
function slateGPSText(s){
 const p=s.location,position=p?coordinateName(p)+(p.accuracy!=null?' · ±'+Math.round(p.accuracy)+' m':''):'';
 if(s.endedAt)return position?tr('Saved GPS')+' · '+position:tr('Location not recorded');
 if(gpsPending.has(s.id))return tr('Refreshing GPS…')+(position?' · '+tr('Previous fix')+': '+position:'');
 if(gpsErrors.has(s.id))return tr('GPS unavailable')+(position?' · '+tr('Previous fix')+': '+position:'');
 return position?position+(p.capturedAt?' · '+slateClock(p.capturedAt,s.timezone):''):tr('Location not recorded');
}
function slateDetailHTML(s,reading){
 return html`${reading?html`<p><b>Reading source</b><br>${e(reading.label||tr('Reading'))} · ${e(reading.instrument)}<br>${e(localTime(reading.measuredAt,s.timezone,true))} · ${e(s.timezone)}<br>${e(tr(reading.protocol))}</p>`:''}<p><b>Location</b><br>${e(gpsText(s))}</p>${weatherHTML(s,true)}<p>Hold the screen facing up here, keep the sensor clear and avoid your shadow. Measure first, then turn the saved slate toward the Sony.</p><p>The QR contains Scout format version, trip ID, stop ID and the large stop code printed above. It identifies this stop; it does not upload anything. Matching currently uses the readable code and timestamps, not automatic QR scanning.</p><p>Lux-derived EV100 is an uncalibrated incident-light estimate (C=250), not the Sony reflected-light meter or exposure compensation.</p>`;
}
async function slate(s,{refreshGPS=true}={}){
 stopMeter();stopSlateTimer();const identity=slateIdentity(s),t=get(state,s.tripId);
 show(html`<div class="slate" data-set="${e(s.id)}"><div class="slate-scroll"><section id="slate-photo"><span class="eyebrow">PHOTOGRAPH THIS WITH YOUR SONY</span><div class="code">${e(s.code)}</div><div id="slate-place"></div><time id="slate-time"></time><small><span>Device clock</span> · <span id="slate-zone">${e(s.timezone)}</span></small><div id="slate-light" class="slate-light">${slateLightHTML(latestSlateReading(state.records,s.id),s.timezone)}</div><small id="slate-gps" role="status"></small><div id="slate-weather">${slateWeatherHTML(s)}</div><div class="slate-identity"><canvas id="qr"></canvas><div><b>${e(t?.name||'')}</b><small>Scout · QR format v2</small><small>Trip ID</small><code>${e(identity.tripId)}</code><small>Stop ID</small><code>${e(identity.setId)}</code></div></div></section><details class="slate-details"><summary>Details & instructions</summary><div id="slate-details-body"></div></details></div><footer class="slate-footer"><p id="slate-status" role="status">${lightCapability.available?tr('Optional: screen up, sensor clear. Measure, then photograph the slate.'):tr('Enter a meter reading if needed, then photograph the slate.')}</p><div class="slate-meter-actions">${lightCapability.available?button(tr('Measure EV + lux · 4 seconds'),'slate-measure',s.id):''}${button(tr('Enter EV / lux'),'slate-reading',s.id)}${button(tr('Cancel measurement'),'slate-stop',s.id,'quiet')}</div><div class="slate-next-actions">${button(tr('Code photographed → continue'),'slate-confirm',s.id,'primary')}${button(tr('Phone only / skip code'),'slate-skip',s.id,'quiet')}</div></footer></div>`);
 const root=$('.slate');root.querySelector('[data-action=slate-stop]').hidden=true;
 // An explicit opening starts one fresh GPS request; returning from meter entry
 // or cancelling a sample keeps this same slate session and does not request again.
 if(refreshGPS&&!s.endedAt)void autoLocate(s.id,{onlyOpen:true});
 await QRCode.toCanvas($('#qr'),JSON.stringify(identity),{width:128,margin:3,errorCorrectionLevel:'M'});
 const tick=()=>{
  if(!modal.open||$('.slate')!==root){stopSlateTimer();return;}
  const current=get(state,s.id)||s,reading=latestSlateReading(state.records,s.id);
  $('#slate-time').textContent=localTime(now(),current.timezone,true);$('#slate-zone').textContent=current.timezone;
  $('#slate-light').innerHTML=slateLightHTML(reading,current.timezone);
  const name=current.location&&current.name===coordinateName(current.location)?tr('Current location'):current.name;
  $('#slate-place').textContent=[name,current.city].filter(Boolean).join(' · ');
  $('#slate-weather').innerHTML=slateWeatherHTML(current);$('#slate-gps').textContent=slateGPSText(current);
  $('#slate-details-body').innerHTML=slateDetailHTML(current,reading);
 };
 tick();slateTimer=setInterval(tick,1000);
}
async function measureSlate(sid){
 const root=$('.slate');if(!root||root.dataset.measuring==='true')return;
 root.dataset.measuring='true';const status=$('#slate-status');
 for(const el of root.querySelectorAll('button'))el.disabled=el.dataset.action!=='slate-stop';
 root.querySelector('[data-action=slate-stop]').hidden=false;
 status.textContent=tr('Measuring… keep still. The reading saves when the sample finishes.');
 try{
  const measured=await measureLight(value=>{if($('.slate')===root)status.textContent=tr('Measuring…')+' '+fmt(value)+' lux';});
  if(!modal.open||$('.slate')!==root)return;
  const set=get(state,sid),r=record('reading',{tripId:set.tripId,setId:sid,label:tr('Slate position'),method:'phone_lux',value:measured.value,instrument:measured.instrument,protocol:'Instructed: screen facing upward, sensor clear at stop; placement and height unverified',calibration:'Uncalibrated phone sensor',measuredAt:now(),samples:{min:measured.min,max:measured.max,count:measured.count,durationMs:measured.durationMs}},local.device.id);
  // Once the sample is complete, finish this small local commit before dismissal.
  root.querySelector('[data-action=slate-stop]').disabled=true;
  await change(current=>{const parent=get(current,sid);if(!parent||parent.deleted)throw Error(tr('Record no longer exists'));put(current,r);});
  if(modal.open&&$('.slate')===root){$('#slate-light').innerHTML=slateLightHTML(r,set.timezone);status.textContent=tr('Light saved. Photograph the code and reading together, then continue.');}
 }catch(err){if(modal.open&&$('.slate')===root)status.textContent=tr('No new reading saved. ')+tr(err.message);}
 finally{if($('.slate')===root){delete root.dataset.measuring;for(const el of root.querySelectorAll('button'))el.disabled=false;root.querySelector('[data-action=slate-stop]').hidden=true;}}
}

function tripDialog(){show(html`<h2>Start a trip</h2><form id="trip-form"><label>Trip name</label><input name="name" placeholder="Hong Kong · October references" maxlength="200"><label>Starting city / destination</label><input name="city" placeholder="Optional; location can fill this later" maxlength="200"><label>Time zone</label><input name="timezone" value="${e(Intl.DateTimeFormat().resolvedOptions().timeZone)}" placeholder="Asia/Hong_Kong" required><label>Starting itinerary</label><select name="template"><option value="blank">Blank · explore anywhere</option><option value="hongkong">Hong Kong reference locations</option></select><p><small>Use an IANA time zone such as Asia/Hong_Kong, Asia/Tokyo or America/Los_Angeles. Each set preserves its capture zone.</small></p><div class="row"><button type="submit" class="primary">Create trip</button>${button(tr('Cancel'),'close')}</div></form>`);}
function readingDialog(sid,measured=null,returnToSlate=false){const s=get(state,sid);show(html`<h2>${measured?tr('Save phone measurement'):tr('Add lighting reading')}</h2><form id="reading-form" data-set="${e(sid)}" data-slate="${returnToSlate?'true':'false'}"><label>Position / zone</label><input name="label" placeholder="Under awning, street center…" required maxlength="200"><div class="form-grid"><div><label>Method</label><select name="method" ${measured?'disabled':''}>${(measured?[['phone_lux',tr('Phone sensor · lux')]]:[['external_lux',tr('External / manual lux')],['camera_ev',tr('Camera meter · EV100')],['manual_ev',tr('External meter · EV100')]]).map(([k,v])=>html`<option value="${k}">${tr(v)}</option>`).join('')}</select></div><div><label>Value</label><input name="value" type="number" step="any" value="${measured?.value??''}" required ${measured?'readonly':''}></div></div><label>Instrument / source</label><input name="instrument" value="${e(measured?.instrument||'')}" placeholder="Meter model or measurement app" required maxlength="200"><label>Orientation / target protocol</label><input name="protocol" placeholder="Phone face upward, at 1.5 m / gray card spot reading…" required maxlength="500"><p><small>${measured?tr('Phone readings are uncalibrated. Stability is not accuracy.'):tr('Enter the meter’s ISO-100 EV reading, not exposure compensation. Keep lux and camera EV separate.')}</small></p><div class="row"><button type="submit" class="primary">Save reading</button>${button(tr('Cancel'),returnToSlate?'slate-return':'close',returnToSlate?sid:'')}</div></form>`);sample=measured;if(returnToSlate){$('#reading-form [name=label]').value=tr('Slate position');$('#reading-form [name=method]').value='camera_ev';$('#reading-form [name=instrument]').value=s.camera.name;}}
function lightingActions(sid){
  const c=lightCapability;
  const android=c.mode==='browser'&&!c.available?html('<p><a class="button" href="')+androidDownload+html('">Download Scout for Android</a></p><small>Includes your notebook, photos and built-in meter in one app. Move existing browser records with Transfer → Field backup, then import the ZIP in Scout for Android.</small>'):'';
  return html('<div class="alert ')+(c.available?'success':'')+html('"><b>')+e(tr(c.title))+html('</b><p>')+e(tr(c.detail))+html('</p>')+android+html('</div><div class="row">')+(c.available?button(tr('Measure light'),'meter',sid,'primary'):'')+button(tr('Manual reading'),'reading',sid,c.available?'':'primary')+html('</div>');
}
async function meter(sid){
  sample=null;
  show(html('<h2>Scout built-in light meter</h2><p id="meter-status">Checking this device…</p>')+button(tr('Cancel'),'close'));
  const status=$('#meter-status');
  lightCapability=await getLightCapability();
  if(!modal.open||$('#meter-status')!==status)return;
  if(!lightCapability.available){show(html('<h2>Lighting on this device</h2>')+lightingActions(sid)+button(tr('Close'),'close'));return;}
  show(html`<h2>Scout built-in light meter</h2><p class="muted">Keep the sensor uncovered and the phone steady. A short sample starts when you tap below.</p><div class="metric" id="meter-value">—</div><p id="meter-status">${e(tr(lightCapability.title))} · uncalibrated</p><div class="row">${button(tr('Capture 4 seconds'),'meter-start',sid,'primary')}${button(tr('Manual reading'),'reading',sid)}${button(tr('Cancel'),'close')}</div>`);
}
function assetDialog(id){const a=get(state,id);show(html`<h2>Image association</h2><p>${e(a.fileName)}</p><details><summary>Original metadata & import notes</summary><p>${e(tr(a.previewSource||tr('Phone reference preview')))}</p><pre>${e(JSON.stringify(a.exif||{},null,2))}</pre><p>${e((a.warnings||[]).join(' · '))}</p></details>${(a.originals||[]).length?html('<h3>')+tr('Original files')+html('</h3>')+a.originals.map((o,i)=>button(tr('Save original')+' · '+e(o.fileName),'save-original',a.id+':'+i)).join(''):html('<p>')+tr('This older record has a preview only; its original was not stored in Scout.')+html('</p>')}${a.phoneCapture?html('<pre>')+e(JSON.stringify(a.phoneCapture,null,2))+html('</pre>'):''}<form id="asset-form" data-id="${e(id)}"><label>Photo set</label><select name="setId"><option value="">Unresolved</option>${sets().map(s=>html`<option value="${e(s.id)}" ${s.id===a.setId?'selected':''}>${e(s.code+' · '+s.name)}</option>`).join('')}</select><label>Reference role</label><select name="role">${roles.map(r=>html`<option value="${e(r)}" ${r===a.role?'selected':''}>${e(tr(r))}</option>`).join('')}</select><label>Tags (comma-separated)</label><input name="tags" value="${e((a.tags||[]).join(', '))}" maxlength="500"><label>Description / observations</label><textarea name="notes" maxlength="4000">${e(a.notes||'')}</textarea><small>${e(a.originalRelativePath||tr('Phone reference'))}<br>${e(a.sha256||'')}</small><p><button type="submit" class="primary">Save association</button> ${button(tr('Cancel'),'close')}</p></form>${button(tr('Archive image record'),'delete',id,'quiet')} ${button(tr('Delete image'),'purge',id,'danger')}`);}
function clocksDialog(){const clocks=active(state,'clock').filter(c=>c.tripId===local.activeTrip),cameras=[...new Set([local.camera||'ILCE-7CR',...fieldAssets().map(a=>a.camera).filter(Boolean)])];show(html`<h2>Camera clock correction</h2><p>Keep the original camera time. These segments only interpret it for matching. Photograph the phone clock to establish each correction.</p>${clocks.map(c=>html`<div class="list-item"><b>${e(c.camera)}</b><p>${e(c.from.slice(0,16))} → ${e(c.to.slice(0,16))}<br>UTC offset ${c.utcOffsetMinutes/60} h · correction ${c.offsetSeconds} s</p>${button(tr('Remove segment'),'delete',c.id,'quiet danger')}</div>`).join('')}<form id="clock-form"><label>Camera model</label><select name="camera">${cameras.map(c=>html`<option>${e(c)}</option>`).join('')}</select><label>Camera wall time · from</label><input type="datetime-local" name="from" required><label>Camera wall time · to</label><input type="datetime-local" name="to" required><div class="form-grid"><div><label>Camera UTC offset (hours)</label><input name="zone" type="number" min="-14" max="14" step="0.25" value="8" required></div><div><label>Add seconds to camera time</label><input name="offset" type="number" min="-172800" max="172800" step="0.1" value="0" required></div></div><p><small>If the camera is 90 seconds slow, enter +90. Use separate segments after clock or time-zone changes. Overlapping segments block suggestions.</small></p><button type="submit" class="primary">Add segment</button> ${button(tr('Close'),'close')}</form>`);}
function saveSetForm(form,redraw=false){
  const sid=selected,version=editVersion,f=new FormData(form),edited=new Set(dirtyFields);
  const fields={name:String(f.get('name')).trim(),city:String(f.get('city')).trim(),mode:f.get('mode'),notes:f.get('notes'),files:f.get('files'),camera:{name:String(f.get('cameraName')).trim()||tr('Unknown camera'),wb:f.get('wb')?Number(f.get('wb')):null,aperture:f.get('aperture')?Number(f.get('aperture')):null,iso:f.get('iso')||'',shutter:f.get('shutter')||''}};
  const save=async()=>{if(version<=(savedVersions.get(sid)??-1))return;const base=get(state,sid);if(!base||base.deleted)return;
    const cameraEdited=[...edited].some(k=>['cameraName','wb','aperture','iso','shutter'].includes(k));
    const changed=Object.fromEntries(Object.entries(fields).filter(([k,v])=>(edited.has(k)||(k==='camera'&&cameraEdited))&&JSON.stringify(v)!==JSON.stringify(base[k])));
    if(Object.hasOwn(changed,'name'))changed.autoName=false;
    if(!Object.keys(changed).length){savedVersions.set(sid,version);if(version===editVersion){formDirty=false;dirtyFields.clear();}savedLabel();return;}
    const incoming=revise(base,changed,local.device.id);let conflicts=0;
    await change(st=>{if(get(st,sid)?.deleted)return;const result=merge(st,[incoming],uid());conflicts=result.conflicts;Object.assign(st,result.state);},redraw);
    savedVersions.set(sid,version);
    if(version===editVersion){formDirty=false;dirtyFields.clear();}savedLabel();
    if(conflicts)notice(tr('Another tab changed this record. Both versions are in Transfer → Conflicts.'),true);
  };
  formSave=formSave.catch(()=>{}).then(save);return formSave;
}

async function importFile(file){if(file.size>MAX_PACKAGE)throw Error(tr('Import limit is 64 MiB. Use smaller desktop batches.'));notice(tr('Reading package and checking attachments…'));
  if(file.name.toLowerCase().endsWith('.json')){const p=JSON.parse(await file.text());if(p.v===1){const records=migrateLegacy(p,'legacy-import');const blobs=[];for(const [id,o]of Object.entries(p.photoData||{})){if(typeof o.d!=='string'||!/^data:image\/(jpeg|png|webp);base64,/.test(o.d))throw Error(tr('Unsupported legacy photo'));const bytes=Uint8Array.from(atob(o.d.split(',')[1]),c=>c.charCodeAt(0));const bid='legacy-'+id,blob=new Blob([bytes],{type:o.d.slice(5,o.d.indexOf(';'))});blobs.push({id:bid,blob,sha256:await sha256(bytes)});const parent=records.find(r=>r.kind==='set'&&r.legacyPoint?.id===o.pointId);if(parent){const r=record('asset',{tripId:'legacy-hk',setId:parent.id,fileName:'Legacy reference '+id,source:'field',blobId:bid,notes:'Original v1 compressed reference.',role:'unclassified'},'legacy-v1','legacy-image-'+id);r.revision=r.id+'-v1';r.updatedAt=parent.startedAt;records.push(r);}}const archive={...p};delete archive.photoData;pendingImport={packet:{packageId:'legacy-'+await sha256(new TextEncoder().encode(JSON.stringify(p))),records,legacy:[archive]},blobs};}
    else throw Error(tr('Use the desktop catalogue ZIP so previews and checksums travel with the metadata.'));
  }else{const files=unpack(new Uint8Array(await file.arrayBuffer()));if(files['field.json'])pendingImport=await decodeField(files);else if(files['catalogue.json']){await importCatalogue(files);return;}else throw Error(tr('Unrecognized ZIP package.'));}
  await refresh();const preview=merge(state,pendingImport.packet.records,pendingImport.packet.packageId),deletions=preview.state.records.filter(r=>r.purgedAt&&!get(state,r.id)?.purgedAt);pendingImport.reviewGeneration=state.generation;pendingImport.purgeCount=deletions.length;show(html`<h2>Review import</h2><p>${preview.added} new records · ${preview.updated} newer versions · ${preview.conflicts} conflicts</p><p>${pendingImport.blobs.length} verified image attachments</p>${preview.duplicate?html('<div class="alert">This package has already been imported.</div>'):''}<p>Conflicting versions are retained for review. Older packages cannot silently undo newer records.</p>${deletions.length?html`<div class="alert"><b>Permanent deletions in this package</b><p>${deletions.length} · ${e(deletions.map(r=>r.name||r.fileName||r.label||r.id).join(' · '))}</p><p>These records cannot be restored in this notebook. Leftover image files can be removed afterward in Storage & cleanup.</p><label class="inline-check"><input id="import-delete-ack" type="checkbox"><span>Apply these deletions to this device.</span></label></div>`:''}<div class="row"><button data-action="apply-import" class="primary" ${deletions.length?'disabled':''}>Apply merge</button>${button(tr('Cancel'),'close')}</div>`);
}
async function importCatalogue(files){if(!trip())throw Error(tr('Select or create the destination trip first.'));const p=JSON.parse(strFromU8(files['catalogue.json']));if(p.format!=='scout-camera'||p.schemaVersion!==1||!Array.isArray(p.assets)||p.assets.length>1000)throw Error(tr('Unsupported camera catalogue.'));const records=[],blobs=[];let duplicates=0;
  for(const a of p.assets){if(!/^[a-f0-9]{64}$/.test(a.sha256)||typeof a.fileName!=='string'||typeof a.originalRelativePath!=='string')throw Error(tr('Invalid camera file manifest.'));const id='camera-'+trip().id+'-'+a.sha256;if(get(state,id)){duplicates++;continue;}let blobId=null;if(a.previewPath){const bytes=files[a.previewPath];if(!bytes||await sha256(bytes)!==a.previewSha256)throw Error(tr('Missing or corrupt camera preview: ')+a.fileName);blobId='preview-'+a.sha256;blobs.push({id:blobId,blob:new Blob([bytes],{type:'image/jpeg'}),sha256:a.previewSha256});}
    records.push(record('asset',{tripId:trip().id,setId:null,source:'camera',fileName:a.fileName,originalRelativePath:a.originalRelativePath,duplicatePaths:a.duplicatePaths||[],sha256:a.sha256,blobId,captureWall:a.captureWall||null,camera:a.camera||tr('Unknown camera'),previewSource:a.previewSource||tr('Imported preview'),exif:a.exif||{},warnings:a.warnings||[],role:'unclassified',notes:'',tags:[]},local.device.id,id));
  }
  validateRecords(records);pendingImport={catalogue:true,packet:{records,packageId:'camera-batch-'+await sha256(files['catalogue.json'])},blobs};show(html`<h2>Camera catalogue</h2><p>${records.length} new camera files · ${duplicates} already catalogued · ${blobs.length} previews</p><p>Files will enter the unresolved inbox for ${e(trip().name)}. Review the clock correction and suggested associations afterward.</p><div class="row">${button(tr('Import catalogue'),'apply-import','','primary')}${button(tr('Cancel'),'close')}</div>`);
}
async function applyImport(){const item=pendingImport;if(!item)return;if(item.purgeCount&&!$('#import-delete-ack')?.checked)throw Error(tr('Review and confirm the deletions first.'));const existing=new Map(snapshot.blobs.map(b=>[b.id,b]));for(const b of item.blobs){const old=existing.get(b.id);if(old&&await sha256(await old.blob.arrayBuffer())!==b.sha256)throw Error(tr('Attachment ID collision. No changes applied.'));}
 await change((s,b,l)=>{if(item.purgeCount&&s.generation!==item.reviewGeneration)throw Error(tr('Notebook changed. Cancel and reopen the import to review it again.'));if(item.catalogue){for(const r of item.packet.records)if(!get(s,r.id))put(s,r);if(!s.packages.includes(item.packet.packageId))s.packages.push(item.packet.packageId);}else{const merged=merge(s,item.packet.records,item.packet.packageId);Object.assign(s,merged.state);for(const legacy of item.packet.legacy||[])if(!get(s,'legacy-hk')?.purgedAt&&!s.legacy.some(x=>JSON.stringify(x)===JSON.stringify(legacy)))s.legacy.push(legacy);}const refs=referencedBlobs(s);for(const blob of item.blobs)if(refs.has(blob.id))b.put(blob);if(!active(s,'trip').some(t=>t.id===l.activeTrip))l.activeTrip=active(s,'trip')[0]?.id||null;const target=l.nextDestination;if(target&&(get(s,target.tripId)?.deleted||get(s,target.recordId)?.deleted))delete l.nextDestination;if(get(s,'legacy-hk')?.purgedAt)s.legacy=[];});pendingImport=null;close();view=item.catalogue?'library':'transfer';selected=null;render();notice(tr('Import committed. Originals unchanged.'));}

async function savePhoneAsset(files,sid,capture=null){
 const assetId=capture?'phone-'+capture.id:uid();if(get(state,assetId))return;
 const prepared=await preparePhotos(files);const metadata=capture?Object.fromEntries(Object.entries(capture).filter(([key])=>!['files','setId','gallery'].includes(key))):null;
 await change((s,b)=>{const set=get(s,sid);if(!set||set.deleted)throw Error(tr('Photo set is archived'));if(get(s,assetId))return;for(const blob of prepared.blobs)b.put(blob);put(s,record('asset',{tripId:set.tripId,setId:sid,source:'field',fileName:files[0].name,blobId:prepared.blobId,originals:prepared.originals,phoneCapture:metadata,previewSource:tr('Rendered phone preview; originals preserved separately'),role:'unclassified',notes:'',tags:[],attachedAt:now()},local.device.id,assetId));},false);
}
async function addPhotos(files,sid){let success=0;const failures=[];for(const file of files){try{await savePhoneAsset([file],sid);success++;}catch(err){failures.push(file.name+': '+tr(err.message));}}
 render();notice(tr('Photos saved')+': '+success+(failures.length?' · '+tr('Failed')+': '+failures.length:''),!!failures.length);if(failures.length)show(html`<h2>Photo import results</h2><pre>${e(failures.join('\n'))}</pre>${button(tr('Close'),'close')}`);
}
function cameraDialog(sid){show(html`<h2>Capture a reference image</h2><p>RAW preserves sensor data. A JPEG or HEIC is already processed by the phone. Scout keeps the original file it receives without recompressing it.</p>${nativeCamera?html`<p>Scout’s camera checks RAW and manual Kelvin support on this phone. Available controls appear inside the camera.</p><p>New camera originals also save to DCIM/Camera in the system gallery.</p>${button(tr('Open Scout camera'),'native-camera',sid,'primary')}`:html`<div class="alert">This browser can open a camera, but cannot select Pro mode, RAW or manual Kelvin. The phone may show a camera chooser.</div>${button(tr('Open phone camera'),'browser-camera',sid,'primary')}`}<p>For the phone’s own Pro mode: open its camera, choose Pro / RAW and set white balance there, then return here and add the saved files. Scout cannot force that mode.</p>${button(tr('Choose existing images'),'photo',sid)} ${button(tr('Cancel'),'close')}`);}
async function acceptCapture(capture){
 const existing=get(state,'phone-'+capture.id);
 if(existing?.deleted)throw Error(tr('Photo set is archived'));
 if(!existing){const files=[];for(const item of capture.files)files.push(await readCaptureFile(item));await savePhoneAsset(files,capture.setId,capture);}
 const published=capture.gallery?capture:await publishCapture(capture.id).catch(()=>capture);
 if(published.gallery?.status!=='saved'){render();show(html`<h2>Reference saved · gallery copy pending</h2><p>Your reference is saved in Scout. The staged originals are retained until the system gallery copy succeeds.</p><p>${e(published.gallery?.error||tr('Gallery storage is unavailable.'))}</p>${button(tr('Retry gallery save'),'retry-gallery',capture.id,'primary')} ${button(tr('Save staged originals'),'share-capture',capture.id)} ${button(tr('Close'),'close')}`);return false;}
 await acknowledgeCapture(capture.id);render();
 notice(tr('Originals saved in Scout and DCIM/Camera.'));if(capture.requestedKelvin&&(capture.actualKelvin!==capture.requestedKelvin||capture.actualAwbMode!==0||capture.actualColorMode!==3))notice(tr('Photo saved, but the camera did not confirm the requested Kelvin. Check image metadata.'),true);
 return true;
}
async function updateDialog(){
 show(html('<h2>Scout updates</h2><p id="update-status">Checking GitHub releases…</p>')+button(tr('Close'),'close'));
 const status=$('#update-status');try{
 if(!native&&'serviceWorker'in navigator){const reg=await navigator.serviceWorker.getRegistration();if(reg){await reg.update();if(reg.installing)await new Promise(resolve=>{const worker=reg.installing,timer=setTimeout(resolve,8000);worker.addEventListener('statechange',()=>{if(['installed','redundant'].includes(worker.state)){clearTimeout(timer);resolve();}},{once:false});});updateReady=!!reg.waiting;$('#update').hidden=!updateReady;}}
 availableUpdate=await checkUpdate();if(!modal.open||$('#update-status')!==status)return;
 show(html`<h2>Scout updates</h2><p>${tr('Installed version')}: ${APP_VERSION}</p>${availableUpdate?html`<p>${tr('Available version')}: ${e(availableUpdate.version)} · ${fmt(availableUpdate.size/1024/1024)} MiB</p><p>Save a field backup first. Android checks the app signature and asks you to approve installation. Keep this app installed to preserve its data.</p>${native?button(tr('Download & install update'),'install-update','','primary'):html`<p>This is the browser edition. Use the web update banner to refresh it, or download Scout for Android from GitHub.</p>`}`:html('<p>No newer compatible Scout build was found.</p>')}<p><a href="${RELEASES_URL}" target="_blank" rel="noopener">Open GitHub releases ↗</a></p>${button(tr('Close'),'close')}`);
 if(!native&&updateReady)modal.insertAdjacentHTML('beforeend',button(tr('Apply browser update'),'update-app','','primary'));
 }catch(err){if(modal.open&&$('#update-status')===status){status.textContent=tr(err.message);if(!native&&updateReady)modal.insertAdjacentHTML('beforeend',button(tr('Apply browser update'),'update-app','','primary'));}}
}

async function colorDialog(id){const a=get(state,id),url=urls.get(a.blobId);if(!url)throw Error(tr('This asset has no preview'));show(html`<h2>Image color reference</h2><p>Click a matte, unclipped area. This samples the rendered preview, not RAW sensor values.</p><canvas id="color-canvas"></canvas><div id="color-result"></div><label>Target / interpretation</label><input id="color-target" value="Sony lens cover · uncalibrated" maxlength="200"><p><small>Keep lighting appearance and neutralized material references separate. This does not measure CCT or physical albedo.</small></p>${button(tr('Save sample in image notes'),'save-color',id,'primary')} ${button(tr('Close'),'close')}`);const img=new Image();await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=reject;img.src=url;});const canvas=$('#color-canvas');const scale=Math.min(1,900/img.width);canvas.width=img.width*scale;canvas.height=img.height*scale;const ctx=canvas.getContext('2d',{willReadFrequently:true});ctx.drawImage(img,0,0,canvas.width,canvas.height);sample=null;
 canvas.onclick=event=>{const rect=canvas.getBoundingClientRect(),x=Math.round((event.clientX-rect.left)*canvas.width/rect.width),y=Math.round((event.clientY-rect.top)*canvas.height/rect.height),left=Math.max(0,x-5),top=Math.max(0,y-5),w=Math.min(11,canvas.width-left),h=Math.min(11,canvas.height-top);const px=ctx.getImageData(left,top,w,h).data,linear=[0,0,0];let clipped=0;for(let i=0;i<px.length;i+=4){for(let j=0;j<3;j++){let v=px[i+j]/255;linear[j]+=v<=.04045?v/12.92:((v+.055)/1.055)**2.4;}if(px[i]>245||px[i+1]>245||px[i+2]>245)clipped++;}linear.forEach((v,i)=>linear[i]=v/(px.length/4));const rgb=linear.map(v=>Math.round(255*(v<=.0031308?v*12.92:1.055*v**(1/2.4)-.055))),hex='#'+rgb.map(v=>v.toString(16).padStart(2,'0')).join('');sample={rgb,hex,x:x/canvas.width,y:y/canvas.height,linear,clipped};$('#color-result').innerHTML=html`<p class="row"><span class="color-chip" style="background:${hex}"></span><b>${hex.toUpperCase()}</b> · sRGB ${rgb.join(', ')}</p>${clipped?html('<div class="alert">Some samples are near clipping. Choose another area.</div>'):''}`;};
}

document.addEventListener('click',async event=>{const el=event.target.closest('[data-action]');if(!el)return;event.preventDefault();const action=el.dataset.action,id=el.dataset.id;try{
 if(!['save-color','close'].includes(action)&&$('#set-form'))await saveSetForm($('#set-form'));
 if(action==='nav'){stopMeter();selectedAssets.clear();view=id;selected=null;render();window.scrollTo(0,0);}
 if(action==='back'){selected=null;render();}
 if(action==='new-trip')tripDialog();
 if(action==='select-trip'){selectedAssets.clear();search='';await change((s,b,l)=>{l.activeTrip=id;});selected=null;view='field';render();}
 if(action==='quick-start'){const zone=Intl.DateTimeFormat().resolvedOptions().timeZone;const r=record('trip',{name:tr('Reference trip')+' · '+new Intl.DateTimeFormat(locale()).format(new Date()),city:'',timezone:zone,template:'blank'},local.device.id);await change((s,b,l)=>{put(s,r);l.activeTrip=r.id;});await newSet();}
 if(action==='slate-confirm'||action==='slate-skip'){await patch(id,{slateStatus:action==='slate-confirm'?'confirmed':'skipped',slateConfirmedAt:action==='slate-confirm'?now():null});close();document.querySelector('#next-step')?.scrollIntoView({block:'start'});}
 if(action==='skip-reference'){await patch(id,{referenceSkipped:true});}
 if(action==='skip-light'){await patch(id,{lightingSkipped:true});}
 if(action==='enable-names'){await change((s,b,l)=>l.onlinePlaceNames=true);await autoLocate(id);}
 if(action==='capture')await beginSet();
 if(action==='place'){const p=itineraryStops(getLanguage()).find(p=>p.key===id);if(p)await beginSet(p.name,p);}
 if(action==='choose-next')chooseNext();
 if(action==='choose-destination')await selectDestination(destinationChoices[Number(id)]);
 if(action==='plan-route'){const target=itineraryStops(getLanguage()).find(p=>p.key===id);if(target)await selectDestination({...target,tripId:local.activeTrip});}
 if(action==='route')routeDialog();
 if(action==='clear-destination')await change((s,b,l)=>{delete l.nextDestination;});
 if(action==='arrive-next'){const target=nextDestination();if(target){close();await beginSet(target.name,target);}}
 if(action==='resume-capture'){const open=get(state,id);if(open&&!open.deleted){await change((s,b,l)=>{l.activeTrip=open.tripId;},false);selected=id;view='field';render();}}
 if(action==='revisit'){const s=get(state,id);await beginSet(s.name,s);}
 if(action==='finish-start'){const next=pendingStop;pendingStop=null;await newSet(next?.name||'',next?.source||null);}
 if(action==='open'){selected=id;view='field';render();window.scrollTo(0,0);}
 if(action==='slate')await slate(get(state,id));
 if(action==='slate-return')await slate(get(state,id),{refreshGPS:false});
 if(action==='slate-measure')await measureSlate(id);
 if(action==='slate-reading')readingDialog(id,null,true);
 if(action==='slate-stop'){stopMeter();await slate(get(state,id),{refreshGPS:false});}
 if(action==='close')close();
 if(action==='finish'){await patch(id,{endedAt:now()});notice(tr('Set finished. The time boundary is saved.'));}
 if(action==='reopen'){if(!confirm(tr('Reopen this interval? New photographs may be included in timestamp suggestions.')))return;await change(s=>{for(const other of active(s,'set').filter(x=>x.tripId===local.activeTrip&&!x.endedAt&&x.id!==id))put(s,revise(other,{endedAt:now()},local.device.id));put(s,revise(get(s,id),{endedAt:null},local.device.id));});}
 if(action==='gps'){el.disabled=true;await autoLocate(id);}
 if(action==='coords'){const s=get(state,id);show(html`<h2>Location & time zone</h2><form id="coords-form" data-id="${e(id)}"><div class="form-grid"><div><label>Latitude (WGS84)</label><input name="lat" type="number" step="any" min="-90" max="90" value="${e(s.location?.lat??'')}" required></div><div><label>Longitude (WGS84)</label><input name="lng" type="number" step="any" min="-180" max="180" value="${e(s.location?.lng??'')}" required></div></div><label>Capture time zone</label><input name="timezone" value="${e(s.timezone)}" required><p><small>Entering coordinates does not claim a GPS fix. Time-zone changes affect display, not the original capture instant.</small></p><button type="submit" class="primary">Save location</button> ${button(tr('Cancel'),'close')}</form>`);}
 if(action==='meter')await meter(id);
 if(action==='meter-start'){el.disabled=true;const status=$('#meter-status');status.textContent=tr('Sampling…');try{const result=await measureLight(v=>{if($('#meter-status')===status&&$('#meter-value'))$('#meter-value').textContent=fmt(v);});if(modal.open&&$('#meter-status')===status)readingDialog(id,{...result,instrument:result.instrument+' · '+local.device.name+' ['+local.device.id.slice(0,8)+']'});}catch(err){if(modal.open&&$('#meter-status')===status){status.textContent=tr('No reading saved. ')+tr(err.message);status.setAttribute('role','alert');if($('#meter-value'))$('#meter-value').textContent='—';}}}
 if(action==='reading'){stopMeter();sample=null;readingDialog(id);}
  if(action==='camera')cameraDialog(id);
 if(action==='browser-camera'){close();const input=$('#camera-file');input.dataset.set=id;input.value='';input.click();}
 if(action==='native-camera'){close();const result=await captureReference({setId:id,language:getLanguage()});if(!result.cancelled)await acceptCapture(result);}
 if(action==='recover-captures'){el.disabled=true;const {captures}=await pendingCaptures();let count=0;for(const capture of captures){try{const retried=await publishCapture(capture.id).catch(()=>capture);if(!await acceptCapture(retried))return;count++;}catch(err){show(html('<h2>Camera recovery</h2><p>')+e(tr(err.message))+html('</p><p>Save these original files separately. Restore an archived stop before retrying its import.</p>')+button(tr('Save staged originals'),'share-capture',capture.id,'primary')+button(tr('Close'),'close'));return;}}notice(tr('Recovered captures')+': '+count);}
 if(action==='retry-gallery'){el.disabled=true;const result=await publishCapture(id);if(await acceptCapture(result))close();}
 if(action==='share-capture')await shareStagedCapture(id);
 if(action==='save-original'){const [assetId,index]=id.split(':');const original=get(state,assetId)?.originals?.[Number(index)];const blob=snapshot.blobs.find(b=>b.id===original?.blobId);if(!blob)throw Error(tr('Original file is unavailable.'));await deliver(original.fileName,new Uint8Array(await blob.blob.arrayBuffer()));}
 if(action==='check-update')await updateDialog();
 if(action==='install-update'){if(!availableUpdate)throw Error(tr('Check for updates first.'));el.disabled=true;el.textContent=tr('Downloading and verifying…');try{await installUpdate(availableUpdate);notice(tr('Android installer opened. Approve the update there.'));}finally{el.textContent=tr('Download & install update');}}

 if(action==='photo'){if(modal.open)close();$('#photo-file').dataset.set=id;$('#photo-file').value='';$('#photo-file').click();}
 if(action==='asset')assetDialog(id);
 if(action==='color')await colorDialog(id);
 if(action==='save-color'){if(!sample?.rgb)throw Error(tr('Choose an image sample first.'));const a=get(state,id);const note=`Image-derived sRGB ${sample.rgb.join(', ')} (${sample.hex}) at ${sample.x.toFixed(3)},${sample.y.toFixed(3)}; target: ${$('#color-target').value}; uncalibrated rendered preview; ${sample.clipped?'near-clipping pixels present':'no near-clipping pixels in sample'}.`;await patch(id,{notes:[a.notes,note].filter(Boolean).join('\n')});close();notice(tr('Color sample saved with the image.'));}
 if(action==='delete'){if(!confirm(tr('Archive this record? It can be restored from Transfer. Originals stay untouched.')))return;await patch(id,{deleted:true});if(modal.open)close();render();}
 if(action==='restore'){const r=get(state,id);if(r?.purgedAt)throw Error(tr('Record no longer exists'));if(get(state,r?.tripId)?.deleted||get(state,r?.setId)?.deleted)throw Error(tr('Restore the parent trip or stop first.'));await patch(id,{deleted:false});}
 if(action==='import'){$('#import-file').value='';$('#import-file').click();}
 if(action==='apply-import'){el.disabled=true;await applyImport();}
 if(action==='resolve-local'||action==='resolve-incoming')await change(s=>resolve(s,id,action==='resolve-incoming',local.device.id));
 if(action==='export'||action==='deletion-export'){if(action==='export'&&!trip())throw Error(tr('Create a trip first'));el.disabled=true;await refresh();exportSnapshot=snapshot;pendingExports=planTripExport(exportSnapshot,action==='deletion-export'?id:trip().id,action==='export'&&id==='handoff');if(pendingExports.length===1){const part=await exportTripPart(exportSnapshot,pendingExports[0]);await deliver(part.filename,part.bytes);await change((s,b,l)=>{l.lastExport=now();});notice(tr('Package handed to your device. Verify the saved file and second copy.'));pendingExports=[];}else{show(html('<h2>Save all ')+pendingExports.length+html(' parts</h2><p>Import every part on the other device. Shared field records merge without duplication. Keep this window open until every part is saved.</p>')+pendingExports.map((x,i)=>html('<p>')+button(tr('Save part ')+(i+1)+' / '+pendingExports.length,'save-part',String(i),'primary')+html(' <small>')+(i+1)+' / '+pendingExports.length+html('</small></p>')).join('')+button(tr('Close'),'close'));}}
 if(action==='save-part'){const x=pendingExports[Number(id)];if(!x)throw Error(tr('Create the export again.'));const part=await exportTripPart(exportSnapshot,x);await deliver(part.filename,part.bytes);await change((s,b,l)=>{l.lastExport=now();},false);el.textContent=tr('Part ')+(Number(id)+1)+' handed to device · save again';}
 if(action==='clocks')clocksDialog();
 if(action==='select-images'){for(const a of visibleAssets())selectedAssets.add(a.id);render();}
 if(action==='clear-images'){selectedAssets.clear();render();}
 if(action==='purge')await cleanupDialog({mode:'records',ids:[id]});
 if(action==='purge-images')await cleanupDialog({mode:'records',ids:[...selectedAssets]});
 if(action==='purge-archived')await cleanupDialog({mode:'archived'});
 if(action==='purge-unused')await cleanupDialog({mode:'unused'});
 if(action==='cleanup-backup'){const target=cleanupPlan?.records.find(r=>r.kind==='trip')?.id||cleanupPlan?.records[0]?.tripId;if(target&&!get(state,target)?.deleted)await change((s,b,l)=>l.activeTrip=target,false);close();cleanupPlan=null;selected=null;view='transfer';render();}
 if(action==='confirm-cleanup'){
  if(!cleanupPlan||!$('#cleanup-ack')?.checked)return;el.disabled=true;const plan=cleanupPlan;
  try{await change((s,b,l)=>applyCleanup(s,b,l,plan),false);}catch(err){if(err.message==='Records changed. Review the cleanup again.'){await cleanupDialog(plan.request);notice(tr(err.message),true);return;}throw err;}
  cleanupPlan=null;pendingExports=[];exportSnapshot=null;pendingImport=null;sample=null;selectedAssets.clear();formDirty=false;dirtyFields.clear();
  if(get(state,selected)?.deleted)selected=null;close();render();notice(tr('Deleted from Scout. Camera album and external files are unchanged.'));
 }

 if(action==='confirm-suggestions'){const clocks=active(state,'clock').filter(c=>c.tripId===local.activeTrip),candidates=fieldAssets().filter(a=>!a.setId&&a.source==='camera').map(a=>({a,result:suggest(a,sets(),clocks)})).filter(x=>x.result.sets.length===1);if(!candidates.length)throw Error(tr('No unique suggestions. Add clock segments and finish photo-set intervals first.'));if(!confirm(`Confirm ${candidates.length} timestamp suggestions? Check your clock segments and set boundaries first. You can change each association later.`))return;await change(s=>{for(const {a,result}of candidates)put(s,revise(get(s,a.id),{setId:result.sets[0].id,association:{method:'time-confirmed',correctedTime:result.time,confirmedAt:now()}},local.device.id));});}
 if(action==='update-app'){if(saving)throw Error(tr('Wait for the current save to finish.')); const reg=await navigator.serviceWorker.getRegistration();if(reg?.waiting){navigator.serviceWorker.addEventListener('controllerchange',()=>location.reload(),{once:true});reg.waiting.postMessage({type:'ACTIVATE'});}else notice(tr('Already up to date.'));}
 }catch(err){notice(err.name==='AbortError'?tr('Cancelled. No export confirmation recorded.'):err.message,true);}finally{if(el.isConnected)el.disabled=false;if(action==='gps'&&el.isConnected)el.textContent=tr('Get fresh GPS');}});

document.addEventListener('submit',async event=>{event.preventDefault();const form=event.target,f=new FormData(form),submit=form.querySelector('[type=submit]');if(submit)submit.disabled=true;try{
 if(form.id==='destination-form'){await selectDestination({key:'custom:'+uid(),tripId:local.activeTrip,name:f.get('name').trim(),city:f.get('city').trim(),timezone:trip().timezone,location:null});}
 if(form.id==='trip-form'){const tz=f.get('timezone').trim();if(!timezoneValid(tz))throw Error(tr('Enter a valid IANA time zone.'));const r=record('trip',{name:f.get('name').trim()||tr('Reference trip'),city:f.get('city').trim(),timezone:tz,template:f.get('template')},local.device.id);await change((s,b,l)=>{put(s,r);l.activeTrip=r.id;});close();view='field';selected=null;render();}
 if(form.id==='kit-form'){await change((s,b,l)=>{l.device.name=f.get('deviceName').trim();l.camera=f.get('camera').trim();l.wb=f.get('wb');l.aperture=f.get('aperture');});notice(tr('Defaults saved for new sets.'));}
 if(form.id==='set-form'){await saveSetForm(form,true);notice(tr('Record saved.'));}
 if(form.id==='coords-form'){const timezone=f.get('timezone').trim();if(!timezoneValid(timezone))throw Error(tr('Invalid time zone'));await patch(form.dataset.id,{timezone,autoTimezone:false,placeLookup:null,location:{lat:Number(f.get('lat')),lng:Number(f.get('lng')),accuracy:null,capturedAt:now(),method:'manual'}});close();}
 if(form.id==='reading-form'){const set=get(state,form.dataset.set),measured=sample;const method=measured?'phone_lux':f.get('method'),value=Number(f.get('value'));if(!Number.isFinite(value)||method.endsWith('lux')&&value<0)throw Error(tr('Enter a valid reading'));const r=record('reading',{tripId:set.tripId,setId:set.id,label:f.get('label').trim(),method,value,instrument:f.get('instrument').trim(),protocol:f.get('protocol').trim(),calibration:measured?'Uncalibrated phone sensor':'Calibration not verified',measuredAt:now(),samples:measured?{min:measured.min,max:measured.max,count:measured.count,durationMs:measured.durationMs}:null},local.device.id);await change(s=>{if(get(s,set.id)?.deleted)throw Error(tr('Record no longer exists'));put(s,r);});sample=null;if(form.dataset.slate==='true')await slate(get(state,set.id),{refreshGPS:false});else close();notice(tr('Measurement saved.'));}
 if(form.id==='asset-form'){await patch(form.dataset.id,{setId:f.get('setId')||null,role:f.get('role'),tags:f.get('tags').split(',').map(s=>s.trim()).filter(Boolean),notes:f.get('notes'),association:{method:'manual',confirmedAt:now()}});close();}
 if(form.id==='clock-form'){const r=record('clock',{tripId:trip().id,camera:f.get('camera'),from:new Date(f.get('from')+'Z').toISOString(),to:new Date(f.get('to')+'Z').toISOString(),utcOffsetMinutes:Number(f.get('zone'))*60,offsetSeconds:Number(f.get('offset'))},local.device.id);await change(s=>put(s,r));clocksDialog();}
 }catch(err){notice(err.message,true);}finally{if(submit?.isConnected)submit.disabled=false;}});
document.addEventListener('change',async event=>{try{if(event.target.id==='import-delete-ack'){modal.querySelector('[data-action=apply-import]').disabled=!event.target.checked;return;}if(event.target.id==='cleanup-ack'){const b=modal.querySelector('[data-action=confirm-cleanup]');if(b)b.disabled=!event.target.checked;return;}if(event.target.matches('[data-select-image]')){const id=event.target.dataset.selectImage;if(event.target.checked)selectedAssets.add(id);else selectedAssets.delete(id);render();return;}if(event.target.id==='online-weather'){await change((s,b,l)=>l.onlineWeather=event.target.checked);return;}if(event.target.id==='place-names'){await change((s,b,l)=>l.onlinePlaceNames=event.target.checked);return;}if(event.target.matches('#trip-form [name=template]')&&event.target.value==='hongkong'){const form=event.target.form;form.elements.timezone.value='Asia/Hong_Kong';if(!form.elements.city.value)form.elements.city.value='Hong Kong';}if(event.target.closest('#set-form')){if(!dirtyFields.has(event.target.name))editVersion++;dirtyFields.add(event.target.name);formDirty=true;await saveSetForm($('#set-form'));}}catch{}});
$('#photo-file').addEventListener('change',event=>{const files=[...event.target.files],sid=event.target.dataset.set;addPhotos(files,sid).catch(err=>notice(err.message,true));});
$('#import-file').addEventListener('change',event=>{if(event.target.files[0])importFile(event.target.files[0]).catch(err=>notice(err.message,true));});
document.addEventListener('input',event=>{if(event.target.id==='destination-search'){renderDestinationList();return;}if(event.target.id==='search'){selectedAssets.clear();search=event.target.value;const pos=event.target.selectionStart;render();$('#search').focus();$('#search').setSelectionRange(pos,pos);}else if(event.target.closest('#set-form')){dirtyFields.add(event.target.name);formDirty=true;editVersion++;const el=$('#saved');if(el)el.textContent=tr('Unsaved edit · leave field to save');}});
$('#camera-file').addEventListener('change',event=>{addPhotos([...event.target.files],event.target.dataset.set).catch(err=>notice(err.message,true));});
$('#language').addEventListener('change',async event=>{const language=event.target.value;try{if($('#set-form'))await saveSetForm($('#set-form'));await change((s,b,l)=>l.language=language);}catch(err){notice(err.message,true);}});
window.addEventListener('beforeunload',event=>{if(saving||formDirty){event.preventDefault();event.returnValue='';}});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&$('#set-form'))saveSetForm($('#set-form')).catch(()=>{});});
modal.addEventListener('close',()=>{stopMeter();stopSlateTimer();});
window.addEventListener('online',connection);window.addEventListener('offline',connection);

async function legacyMigration(){if(local.legacyMigrated)return;let raw;try{raw=localStorage.getItem('hkscout_v1');}catch{}if(!raw){await change((s,b,l)=>l.legacyMigrated=true,false);return;}
 const old=JSON.parse(raw),records=migrateLegacy(old,'legacy-browser');let photos=[];
 photos=await new Promise((resolve,reject)=>{const q=indexedDB.open('hkscout');let created=false;q.onupgradeneeded=()=>created=true;q.onerror=()=>reject(q.error);q.onsuccess=()=>{const db=q.result;if(created||!db.objectStoreNames.contains('photos')){db.close();resolve([]);return;}const tx=db.transaction('photos');const a=tx.objectStore('photos').getAll();tx.oncomplete=()=>{db.close();resolve(a.result||[]);};tx.onerror=()=>reject(tx.error);};});
 const blobs=[];for(const p of photos){const parent=records.find(r=>r.kind==='set'&&r.legacyPoint?.id===p.pointId);if(!parent)continue;const id='legacy-'+p.id;blobs.push({id,blob:p.blob,sha256:await sha256(await p.blob.arrayBuffer())});const r=record('asset',{tripId:'legacy-hk',setId:parent.id,source:'field',fileName:'Legacy reference '+p.id,blobId:id,role:'unclassified',notes:'Original v1 compressed reference.'},'legacy-v1','legacy-image-'+p.id);r.revision=r.id+'-v1';r.updatedAt=parent.startedAt;records.push(r);}
 await change((s,b,l)=>{for(const r of records)put(s,r);for(const blob of blobs)b.put(blob);s.legacy.push(old);l.legacyMigrated=true;l.activeTrip='legacy-hk';},false);notice(tr('Your original Hong Kong records were migrated. The v1 source was preserved.'));
}
async function boot(){try{await store.open();await refresh();await legacyMigration();lightCapability=await getLightCapability();render();if(sets().some(s=>!s.endedAt))notice(tr('An open photo set was recovered. Continue it or finish it before moving on.'));navigator.storage?.persist?.().catch(()=>{});if('serviceWorker'in navigator&&!native&&location.protocol!=='file:'){const reg=await navigator.serviceWorker.register('./sw.js');const offer=()=>{updateReady=!!reg?.waiting;$('#update').hidden=!updateReady;if(updateReady)notice(tr('An app update is ready. Use Update app when your capture is saved.'));};reg?.addEventListener('updatefound',()=>reg.installing?.addEventListener('statechange',offer));offer();}}catch(err){app.innerHTML=html`<section class="card"><h1>Could not open the notebook</h1><p>${e(err.message)}</p><p>Your existing browser data has not been cleared. Export the v1 data from another existing tab if migration needs repair.</p></section>`;}}
boot();

function nextStep(s,assets,readings){
 if(s.endedAt)return html`<section class="card success" id="next-step"><h2>Stop complete</h2><p>Choose where to go next, or export a backup when you finish shooting.</p>${button(tr('Choose next stop'),'choose-next','','primary')} ${button(tr('Capture here now'),'capture')}${button(tr('Back up this trip'),'export','backup')}</section>`;
 let title,detail,actions;
 if(!s.slateStatus){title=tr('1 · Photograph the Sony code');detail=tr('This connects your Sony originals to this stop. Skip it when using only your phone.');actions=button(tr('Show camera slate'),'slate',s.id,'primary')+button(tr('Phone only / skip code'),'slate-skip',s.id);}
 else if(!assets.length&&!s.referenceSkipped){title=tr('2 · Take a phone reference');detail=tr('Capture a useful view here. The original file stays intact.');actions=button(tr('Take reference photo'),'camera',s.id,'primary')+button(tr('Use an existing image'),'photo',s.id)+button(tr('Sony only / skip phone photo'),'skip-reference',s.id,'quiet');}
 else if(!readings.length&&!s.lightingSkipped){title=tr('3 · Record the light, if needed');detail=tr('Measure here or enter a meter reading. You can skip this for a quick visual reference.');actions=button(tr(lightCapability.available?'Measure light':'Add a light reading'),lightCapability.available?'meter':'reading',s.id,'primary')+button(tr('Skip lighting'),'skip-light',s.id);}
 else{title=tr('4 · Finish this stop');detail=tr('Take Sony RAW references and details, then finish to save the time boundary.');actions=button(tr('Finish stop'),'finish',s.id,'primary');}
 return html`<section class="card next-step" id="next-step"><div class="eyebrow">NEXT ACTION</div><h2>${title}</h2><p>${detail}</p><div class="row">${actions}${title!==tr('4 · Finish this stop')?button(tr('Finish stop now'),'finish',s.id,'quiet'):''}</div><small>${tr(gpsPending.has(s.id)?'GPS is being saved in the background.':'Your notes and reference images stay editable.')}</small>${!nativePlaceNames&&!local.onlinePlaceNames&&!s.placeLookup?'<p>'+button(tr('Enable online area names'),'enable-names',s.id,'quiet')+'</p><small>'+tr('Sends this device’s current GPS to BigDataCloud. Coordinates alone also work.')+'</small>':''}</section>`;
}
async function autoLocate(id,{onlyOpen=false}={}){
 if(onlyOpen&&get(state,id)?.endedAt)return;
 if(gpsPending.has(id))return;gpsPending.add(id);gpsErrors.delete(id);render();
 const previous=get(state,id)?.location?.capturedAt;
 try{
  const fix=await locate();
  let accepted=false;
  await change(s=>{const current=get(s,id);if(!current||current.deleted||(onlyOpen&&current.endedAt)||current.location?.capturedAt!==previous)return;const updates={location:fix,placeLookup:null};if(current.autoName)updates.name=coordinateName(fix);put(s,revise(current,updates,local.device.id));accepted=true;});
  if(!accepted)return;
  void autoWeather(id,fix);
  const online=local.onlinePlaceNames===true||(nativePlaceNames&&local.onlinePlaceNames!==false);
  if(online&&navigator.onLine){
   try{
    const place=await Promise.race([nativePlaceNames?lookupNativePlace({...fix,language:getLanguage()}):lookupBrowserArea(fix,getLanguage()),new Promise(resolve=>setTimeout(()=>resolve(null),8000))]);
    if(place?.name)await change(s=>{const current=get(s,id);if(!current||(onlyOpen&&current.endedAt))return;const updates=automaticPlaceChanges(current,fix,place);if(Object.keys(updates).length)put(s,revise(current,updates,local.device.id));});
   }catch{/* Coordinates remain useful offline or when the provider is unavailable. */}
  }
 }catch{gpsErrors.set(id,tr('GPS unavailable. Keep shooting, retry GPS, or enter coordinates later.'));}
 finally{gpsPending.delete(id);render();}
}

let pendingStop=null;
async function beginSet(name='',source=null){const open=ownOpenSets(state,local.device.id);if(!open.length){await newSet(name,source);return;}pendingStop={name,source};show(html`<h2>Finish the current stop first?</h2><p>${open.map(s=>e(get(state,s.tripId)?.name||'')+' · '+e(s.name)).join('<br>')}</p><p>Starting the next stop finishes these open captures on this device, including other trips.</p>${button(tr('Finish & start next stop'),'finish-start','','primary')} ${button(tr('Keep current stop'),'close')}`);}

let destinationChoices=[];
function nextDestination(){return local.nextDestination?.tripId===local.activeTrip?local.nextDestination:null;}
function nextDestinationCard(){const target=nextDestination();return target?html`<section class="card next-destination"><div class="eyebrow">YOUR CHOSEN NEXT STOP</div><h2>${e(target.name)}</h2><p class="muted">${e(target.group||target.city||'')}</p><div class="row">${button(tr('Directions & arrival'),'route','','primary')}${button(tr('Change destination'),'choose-next')} ${button(tr('Clear destination'),'clear-destination','','quiet')}</div></section>`:'';}
function captureElsewhere(){const open=ownOpenSets(state,local.device.id).filter(s=>s.tripId!==local.activeTrip);return open.length?html`<section class="card alert"><b>Unfinished capture in another trip</b><p>${open.map(s=>e(get(state,s.tripId)?.name||'')+' · '+e(s.name)).join('<br>')}</p>${button(tr('Return to capture'),'resume-capture',open[0].id)}</section>`:'';}
function chooseNext(){
 destinationChoices=nextStopChoices(trip(),fieldsets(),getLanguage()).map(c=>({...c,tripId:trip().id}));
 show(html`<div class="destination-picker"><h2>Choose your next stop</h2><p>Pick any planned or recorded place, or enter a new destination. A new capture starts only after you arrive.</p><label for="destination-search">Find a destination</label><input id="destination-search" type="search" placeholder="Place or day"><div id="destination-list"></div><details><summary>Somewhere else</summary><form id="destination-form"><label>Destination / address</label><input name="name" maxlength="300" required><label>City / area</label><input name="city" value="${e(trip().city)}" maxlength="200"><p><button type="submit" class="primary">Choose this destination</button></p></form></details><div class="destination-footer">${button(tr('Close'),'close')}</div></div>`);
 renderDestinationList();
}
function renderDestinationList(){const query=($('#destination-search')?.value||'').trim().toLocaleLowerCase();const list=$('#destination-list');if(!list)return;let group='';list.innerHTML=destinationChoices.map((c,index)=>{
 if(query&&![c.name,c.city,c.group].join(' ').toLocaleLowerCase().includes(query))return '';
 const heading=group!==c.group?html`<h3>${e(c.group)}</h3>`:'';group=c.group;
 const count=c.plannedStopKey?sets().filter(s=>s.plannedStopKey===c.plannedStopKey&&s.endedAt).length:0;
 return heading+html`<div class="destination-option"><div><b>${e(c.name)}</b>${count?html`<small>${tr('Finished captures')}: ${count}</small>`:''}</div>${button(tr('Choose'),'choose-destination',String(index))}</div>`;
 }).join('')||html('<p>No matching places. Enter a destination below.</p>');}
async function selectDestination(target){if(!target||target.tripId!==local.activeTrip)throw Error(tr('Choose a destination in the current trip.'));await change((s,b,l)=>{l.nextDestination=target;});routeDialog();}
function routeDialog(){const target=nextDestination();if(!target){chooseNext();return;}
 show(html`<div class="route-dialog"><div class="route-scroll"><h2>${e(target.name)}</h2><p>${e(target.group||target.city||'')}</p><h3>How would you like to get there?</h3><small>Google Maps</small><div class="route-options">${[['walking','Walking route'],['transit','Public transport'],['driving','Driving route']].map(([mode,label])=>html`<a class="button" data-travel-mode="${mode}" href="${e(directionsURL(target,mode))}" target="_blank" rel="noopener noreferrer">${tr(label)} ↗</a>`).join('')}</div><p><a class="button" data-amap="true" href="${e(amapSearchURL(target))}" target="_blank" rel="noopener noreferrer">Open destination in Amap ↗</a></p><small>For mainland China: confirm the place in Amap, then choose its route button and travel mode.</small><details><summary>Route details</summary><p>Maps uses your current location and shows route options, journey times and transfers. Check the destination and entrance before leaving.</p><small>Opening a route sends the chosen destination to Google Maps. Internet is normally needed; Scout keeps your destination offline.</small><p>Arriving and starting a capture are separate steps. Your previous capture keeps its original GPS and time.</p></details></div><div class="route-footer">${button(tr('Arrived · start capture'),'arrive-next','','primary')}<div class="row">${button(tr('Choose another stop'),'choose-next')}${button(tr('Close'),'close')}</div></div></div>`);
}


const fileSize=bytes=>bytes<1024?bytes+' B':bytes<1048576?(bytes/1024).toFixed(1)+' KiB':(bytes/1048576).toFixed(1)+' MiB';
function storagePanel(){
 const refs=referencedBlobs(state),unused=snapshot.blobs.filter(b=>!refs.has(b.id)),archived=state.records.filter(r=>r.deleted&&!r.purgedAt);
 return html`<section class="card"><h2>Storage & cleanup</h2><p><b>${fileSize(snapshot.blobs.reduce((n,b)=>n+b.blob.size,0))}</b> · ${tr('Scout image storage on this device')}</p><p>${tr('Unused files')}: ${unused.length} · ${fileSize(unused.reduce((n,b)=>n+b.blob.size,0))}<br>${tr('Archived records')}: ${archived.length}</p><div class="row">${unused.length?button(tr('Clean unused files'),'purge-unused'):''}${archived.length?button(tr('Delete archived records'),'purge-archived','','danger'):''}</div><p>Delete individual images in Library, or delete a whole trip above. Archived stops may still have linked images; review the counts before deleting.</p><small>Only Scout’s notebook copies are removed. Camera album, Sony files, saved ZIP backups, staged camera recovery files and original v1 data remain separate.</small></section>`;
}
function deletionHistory(){const trips=state.records.filter(r=>r.kind==='trip'&&r.purgedAt);return trips.length?html`<details class="card"><summary>Deleted trips · ${trips.length}</summary><p>These are small deletion records, not recoverable trips. Export one only if you want to apply its deletions on another device; review the import there.</p>${trips.map(t=>html`<div class="list-item"><b>${e(t.name)}</b><p>${button(tr('Export deletion record'),'deletion-export',t.id)}</p></div>`).join('')}</details>`:'';}
async function cleanupDialog(request){
 await refresh();const plan=planCleanup(snapshot,request);cleanupPlan=plan;
 if(!plan.records.length&&!plan.blobIds.length){cleanupPlan=null;if(modal.querySelector('.cleanup-dialog'))close();render();notice(tr('Nothing to clean up.'));return;}
 const title=plan.counts.trip?tr('Delete trip'):plan.counts.set?tr('Delete stop'):plan.counts.asset?tr('Delete images'):tr('Clean up Scout');
 const backupTrip=plan.records.find(r=>r.kind==='trip')||get(state,plan.records[0]?.tripId);
 show(html`<div class="cleanup-dialog"><div class="cleanup-scroll"><h2>${title}</h2><p class="cleanup-names">${e(plan.records.find(r=>r.kind==='trip')?.name||plan.records.find(r=>r.kind==='set')?.name||plan.records[0]?.fileName||'')}</p><div class="cleanup-counts">${[['trip','Trips'],['set','Stops'],['asset','Images'],['reading','Light readings'],['clock','Clock segments']].filter(([key])=>plan.counts[key]).map(([key,label])=>html`<span>${tr(label)}: <b>${plan.counts[key]}</b></span>`).join('')}</div><p><b>${tr('Image storage to free')}: ${fileSize(plan.bytes)}</b><br><small>${tr('Stored files')}: ${plan.blobIds.length}${plan.shared?' · '+tr('Shared files kept')+': '+plan.shared:''}</small></p><p>Removes selected records and their linked images and readings from Scout on this device. Stored originals and previews are permanently removed when no other record needs them.</p><p class="alert">Camera album / DCIM, Sony originals and existing ZIP backups stay untouched. This cannot be undone in Scout. Export a backup first if you may need these records.</p><details><summary>Review items & deletion details</summary><ul class="cleanup-items">${plan.records.map(r=>html`<li>${tr({trip:'Trip',set:'Stop',asset:'Image',reading:'Reading',clock:'Clock segment'}[r.kind])} · ${e(r.name||r.fileName||r.label||r.camera||r.id)}</li>`).join('')}</ul><small>Small deletion records retain names, IDs and revision history to prevent old imports from restoring deleted items. This is local cleanup; other devices change only when you import a deletion package. Staged camera recovery files and original v1 data are separate.</small></details></div><div class="cleanup-footer"><label class="inline-check"><input type="checkbox" id="cleanup-ack"><span>I understand this permanently removes Scout’s copies.</span></label><div class="row"><button class="danger" data-action="confirm-cleanup" disabled>Delete permanently</button>${button(tr('Cancel'),'close')}${backupTrip&&!backupTrip.deleted?button(tr('Back up first'),'cleanup-backup'):''}</div></div></div>`);
}
